import{_ as r}from"./chunks/backup.DhSKeS3C.js";import{_ as n,o,c as l,a2 as i}from"./chunks/framework.DSc8fo6x.js";const h=JSON.parse('{"title":"Backup və bərpa","description":"","frontmatter":{},"headers":[],"relativePath":"backup.md","filePath":"backup.md"}'),e={name:"backup.md"};function t(d,a,s,p,u,b){return o(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="backup-və-bərpa" tabindex="-1">Backup və bərpa <a class="header-anchor" href="#backup-və-bərpa" aria-label="Permalink to &quot;Backup və bərpa&quot;">​</a></h1><p><img src="'+r+'" alt="Backup"></p><h2 id="proqram-ozu-backup-edir" tabindex="-1">Proqram özü backup edir <a class="header-anchor" href="#proqram-ozu-backup-edir" aria-label="Permalink to &quot;Proqram özü backup edir&quot;">​</a></h2><ul><li>Mütəmadi (adətən 20 saatdan bir) və <strong>bağlananda</strong>.</li><li>Yeniləmədən və bərpadan əvvəl ayrıca backup.</li><li><a href="./telegram.html">Telegram</a> qoşulubsa — gündə bir dəfə telefona.</li></ul><h2 id="həftədə-bir-dəfə-usb" tabindex="-1">Həftədə bir dəfə: USB <a class="header-anchor" href="#həftədə-bir-dəfə-usb" aria-label="Permalink to &quot;Həftədə bir dəfə: USB&quot;">​</a></h2><p>USB fləşi taxın → <strong>Backup</strong> → <strong>Ən son backup-ı … diskinə köçür</strong>. USB-ni kompüterin yanında saxlamayın.</p><h2 id="bərpa-kodu" tabindex="-1">Bərpa kodu <a class="header-anchor" href="#bərpa-kodu" aria-label="Permalink to &quot;Bərpa kodu&quot;">​</a></h2><p><strong>Backup → Bərpa kodu</strong> → parolunuz. Kağıza yazılmalıdır — kompüter xarab olsa, onsuz məlumat qaytarılmır.</p><h2 id="backup-ı-bərpa-etmək" tabindex="-1">Backup-ı bərpa etmək <a class="header-anchor" href="#backup-ı-bərpa-etmək" aria-label="Permalink to &quot;Backup-ı bərpa etmək&quot;">​</a></h2><p>Səhvən nəsə pozulubsa:</p><ul><li>siyahıda backup-ın yanında <strong>Bərpa et</strong> → admin parolu.</li></ul><h3 id="fayldan-berpa" tabindex="-1">Fayldan bərpa <a class="header-anchor" href="#fayldan-berpa" aria-label="Permalink to &quot;Fayldan bərpa {#fayldan-berpa}&quot;">​</a></h3><p>USB-dəki və ya Telegram-dan yüklənmiş faylı: <strong>Fayldan bərpa</strong> → faylı seçin → admin parolu.</p><ul><li><strong>Telegram-dan hissələr gəlibsə (<code>.001</code>, <code>.002</code>…)</strong> — hamısını yükləyin və <strong>hamısını birlikdə</strong> seçin (Ctrl ilə).</li><li>Fayl başqa kompüterdəndirsə — həmin quraşdırmanın <strong>bərpa kodunu</strong> da yazın.</li></ul><p>Bərpadan sonra hamı yenidən daxil olur. Bərpadan əvvəlki vəziyyət &quot;Bərpadan əvvəl&quot; backup-ı kimi qalır — heç nə itmir.</p><h2 id="berpa-ekrani" tabindex="-1">Bərpa ekranı <a class="header-anchor" href="#berpa-ekrani" aria-label="Permalink to &quot;Bərpa ekranı {#berpa-ekrani}&quot;">​</a></h2><p>Baza silinsə, zədələnsə, açar itsə və ya proqramın köhnə versiyası qalıbsa, adi ekran əvəzinə <strong>Bərpa</strong> ekranı açılır. Səbəb yuxarıda yazılır.</p><ol><li><strong>Bərpa kodunu</strong> (kağızdakı) yazın.</li><li>Seçin: <strong>Bu backup-ı bərpa et</strong>, <strong>Fayldan bərpa</strong> (USB, Telegram), <strong>Açarı bərpa et</strong> və ya <strong>Yenidən yoxla</strong>.</li><li><strong>Boş bazadan başla</strong> — yalnız heç bir backup yoxdursa.</li></ol><p>Bərpa kodu olmadan bu ekranda heç nə etmək olmur — məlumatlar qorunur. &quot;Proqramın köhnə versiyası&quot; yazılıbsa — sadəcə ən son versiyanı quraşdırın.</p><h2 id="diqqət-baza-kohnə-nusxə-ilə-əvəz-edilib" tabindex="-1">&quot;DİQQƏT: baza köhnə nüsxə ilə əvəz edilib!&quot; <a class="header-anchor" href="#diqqət-baza-kohnə-nusxə-ilə-əvəz-edilib" aria-label="Permalink to &quot;&quot;DİQQƏT: baza köhnə nüsxə ilə əvəz edilib!&quot;&quot;">​</a></h2><p>Proqram bağlı ikən kimsə məlumat faylını köhnə nüsxə ilə dəyişib — arada edilmiş satışlar itmiş ola bilər. Telegram və USB-dəki backup-ları yoxlayın, lazımdırsa daha yenisini bərpa edin, sonra <strong>Gördüm</strong>.</p><h2 id="komputer-xarab-oldu" tabindex="-1">Kompüter xarab oldu <a class="header-anchor" href="#komputer-xarab-oldu" aria-label="Permalink to &quot;Kompüter xarab oldu {#komputer-xarab-oldu}&quot;">​</a></h2><p>Yeni kompüterdə Kassa-nı quraşdırın → ilk açılışda müvəqqəti admin yaradın → <strong>Backup → Fayldan bərpa</strong> (USB və ya Telegram faylı) + köhnə quraşdırmanın <strong>bərpa kodu</strong>. Köhnə istifadəçilər, mallar və ayarlar qayıdır.</p>',23)])])}const c=n(e,[["render",t]]);export{h as __pageData,c as default};
